/**
 * The MolaPlus product range, from the official MolaPlus Group dealer guide
 * (2026 edition). Single source of truth for the Products page, the order
 * form, structured data and the server's list of orderable products
 * (backend/public_html/api/_catalog.php, generated by scripts/sync-catalog.mjs).
 *
 * Keep wording faithful to the guide: do not add claims, prices or figures
 * that it does not contain.
 */

export type CategoryId = "dairy" | "poultry" | "livestock" | "crops";

export type Category = {
  id: CategoryId;
  eyebrow: string;
  name: string;
  tagline: string;
};

export type Product = {
  id: string;
  name: string;
  category: CategoryId;
  sizes: string[];
  image: string;
  /** One or two sentences: what it is and who it is for. */
  summary: string;
  /** Expected results, as listed in the guide. */
  results: string[];
  /** How to use, condensed from the guide. */
  usage: string[];
  /** Dedicated product page, when there is one. */
  detailHref?: string;
};

