/** Order-form line items: one per product pack size, e.g. "Super Milk Booster — 1KG". */
export function orderItems(): [name: string, image: string][] {
  return products.flatMap((p) => p.sizes.map((size) => [`${p.name} — ${size}`, p.image] as [string, string]));
}

export function productsIn(category: CategoryId) {
  return products.filter((p) => p.category === category);
}
